"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9945],{20755:e=>{e.exports=JSON.parse('{"functions":[{"name":"unload","desc":"Unloads every chunk beyond the unload radius. Runs in `Phases.Last`, so a\\nchunk is never destroyed in the same frame something else was still building\\ninto it.\\n\\nThe unload radius sits one chunk beyond the load radius, giving a band where\\na chunk is neither generated nor destroyed \u2014 without it, walking back and\\nforth over a chunk boundary would rebuild the same chunk repeatedly.\\n\\nStale chunks are collected before any are removed, because unloading mutates\\nthe registry table being iterated.","params":[{"name":"world","desc":"","lua_type":"jecs.World"}],"returns":[{"desc":"Update function.","lua_type":"() -> ()"},{"desc":"Cleanup function.","lua_type":"() -> ()"}],"function_type":"static","source":{"line":37,"path":"src/main/server/systems/maze/unload.luau"}}],"properties":[],"types":[],"name":"unload","desc":"Destroys chunks that every observer has walked away from.","tags":["server-system"],"realm":["Server"],"source":{"line":8,"path":"src/main/server/systems/maze/unload.luau"}}')}}]);